sealed interface Expr { val kids: List<Expr> }
data class Add(val left: Expr, val right: Expr) : Expr { override val kids get() = listOf(left, right) }
data class Lit(val v: Int) : Expr { override val kids get() = emptyList() }

fun rewrite(e: Expr): Expr = when (val n = e.mapChildren(::rewrite)) {   // engine: bottom-up
    is Add -> if (n.right is Lit && n.right.v == 0) n.left else n        // x + 0 -> x
    else -> n
}
